1	package com.example.starter.transition.service;
2	
3	import com.example.starter.transition.ApiException;
4	import com.example.starter.transition.TransitionStatus;
5	import com.example.starter.transition.dto.ApplyOrderRequest;
6	import com.example.starter.transition.dto.DisposeRollsRequest;
7	import com.example.starter.transition.dto.ExecuteOrderRequest;
8	import com.example.starter.transition.dto.IdempotentResult;
9	import com.example.starter.transition.dto.InspectionRequest;
10	import com.example.starter.transition.dto.OrderView;
11	import com.example.starter.transition.dto.ReexamRequest;
12	import com.example.starter.transition.dto.RollView;
13	import com.example.starter.transition.dto.TransitionRecomputeView;
14	import com.example.starter.transition.model.Grade;
15	import com.example.starter.transition.model.IdempotentRequest;
16	import com.example.starter.transition.model.RollInspection;
17	import com.example.starter.transition.model.TransitionOrder;
18	import com.example.starter.transition.model.TransitionRoll;
19	import com.example.starter.transition.repo.CleaningWindowRepository;
20	import com.example.starter.transition.repo.GradeRepository;
21	import com.example.starter.transition.repo.IdempotentRequestRepository;
22	import com.example.starter.transition.repo.LateEventRepository;
23	import com.example.starter.transition.repo.MachineSlotRepository;
24	import com.example.starter.transition.repo.RollInspectionRepository;
25	import com.example.starter.transition.repo.TransitionOrderRepository;
26	import com.example.starter.transition.repo.TransitionRollRepository;
27	import com.example.starter.transition.repo.VerdictEventRepository;
28	import com.example.starter.transition.support.FingerprintUtil;
29	import com.fasterxml.jackson.core.type.TypeReference;
30	import com.fasterxml.jackson.databind.ObjectMapper;
31	import org.springframework.dao.DuplicateKeyException;
32	import org.springframework.stereotype.Service;
33	import org.springframework.transaction.annotation.Transactional;
34	
35	import java.math.BigDecimal;
36	import java.nio.charset.StandardCharsets;
37	import java.security.SecureRandom;
38	import java.time.Clock;
39	import java.time.LocalDateTime;
40	import java.time.format.DateTimeFormatter;
41	import java.util.HexFormat;
42	import java.util.List;
43	import java.util.Optional;
44	
45	/**
46	 * 造纸机改品种过渡料控制服务。
47	 *
48	 * <p>流转：申请→方式判定→执行→过渡料处置→完成→归档（终态）。</p>
49	 */
50	@Service
51	public class TransitionService {
52	
53	    static final String BIZ_APPLY = "APPLY_ORDER";
54	    static final String BIZ_INSPECTION = "SUBMIT_INSPECTION";
55	    static final String BIZ_REEXAM = "SUBMIT_REEXAM";
56	
57	    static final String INSPECTION_INITIAL = "INITIAL";
58	    static final String INSPECTION_REEXAM = "REEXAM";
59	
60	    private static final DateTimeFormatter NO_FORMAT = DateTimeFormatter.ofPattern("yyyyMMddHHmmss");
61	    private static final SecureRandom RANDOM = new SecureRandom();
62	
63	    private final GradeRepository gradeRepository;
64	    private final TransitionOrderRepository orderRepository;
65	    private final MachineSlotRepository machineSlotRepository;
66	    private final CleaningWindowRepository cleaningWindowRepository;
67	    private final TransitionRollRepository rollRepository;
68	    private final RollInspectionRepository inspectionRepository;
69	    private final VerdictEventRepository verdictEventRepository;
70	    private final IdempotentRequestRepository idempotentRequestRepository;
71	    private final LateEventRepository lateEventRepository;
72	    private final ObjectMapper objectMapper;
73	    private final Clock clock;
74	
75	    public TransitionService(GradeRepository gradeRepository,
76	                             TransitionOrderRepository orderRepository,
77	                             MachineSlotRepository machineSlotRepository,
78	                             CleaningWindowRepository cleaningWindowRepository,
79	                             TransitionRollRepository rollRepository,
80	                             RollInspectionRepository inspectionRepository,
81	                             VerdictEventRepository verdictEventRepository,
82	                             IdempotentRequestRepository idempotentRequestRepository,
83	                             LateEventRepository lateEventRepository,
84	                             ObjectMapper objectMapper,
85	                             Clock clock) {
86	        this.gradeRepository = gradeRepository;
87	        this.orderRepository = orderRepository;
88	        this.machineSlotRepository = machineSlotRepository;
89	        this.cleaningWindowRepository = cleaningWindowRepository;
90	        this.rollRepository = rollRepository;
91	        this.inspectionRepository = inspectionRepository;
92	        this.verdictEventRepository = verdictEventRepository;
93	        this.idempotentRequestRepository = idempotentRequestRepository;
94	        this.lateEventRepository = lateEventRepository;
95	        this.objectMapper = objectMapper;
96	        this.clock = clock;
97	    }
98	
99	    /** 申请改品种单（requestId 幂等；同一纸机同时刻唯一受理）。 */
100	    @Transactional
101	    public IdempotentResult<OrderView> apply(ApplyOrderRequest request) {
102	        String fingerprint = FingerprintUtil.sha256(request.requestId(), request);
103	        IdempotentRequest existing = lookupIdempotent(request.requestId(), BIZ_APPLY, fingerprint);
104	        if (existing != null) {
105	            return replay(existing, new TypeReference<OrderView>() {
106	            });
107	        }
108	
109	        Grade fromGrade = gradeRepository.findByCode(request.fromGrade())
110	                .orElseThrow(() -> ApiException.badRequest("原品种不存在: " + request.fromGrade()));
111	        Grade toGrade = gradeRepository.findByCode(request.toGrade())
112	                .orElseThrow(() -> ApiException.badRequest("新品种不存在: " + request.toGrade()));
113	
114	        // 纸机占用：唯一索引保证同一纸机同时刻唯一受理；失败随事务回滚，不留幂等占位。
115	        String orderNo = newOrderNo();
116	        if (!machineSlotRepository.tryOccupy(request.paperMachine(), orderNo)) {
117	            throw ApiException.conflict("纸机 " + request.paperMachine() + " 已有执行中改品种单");
118	        }
119	
120	        TransitionOrder order = new TransitionOrder();
121	        order.setOrderNo(orderNo);
122	        order.setPaperMachine(request.paperMachine());
123	        order.setFromGrade(fromGrade.getGradeCode());
124	        order.setToGrade(toGrade.getGradeCode());
125	        order.setBasisWeightFrom(fromGrade.getBasisWeight());
126	        order.setBasisWeightTo(toGrade.getBasisWeight());
127	        order.setAshLevelFrom(fromGrade.getAshLevel());
128	        order.setAshLevelTo(toGrade.getAshLevel());
129	        order.setStatus(TransitionStatus.APPLIED);
130	        order.setAppliedRequestId(request.requestId());
131	        order.setAppliedAt(now());
132	        orderRepository.insert(order);
133	
134	        registerIdempotent(request.requestId(), BIZ_APPLY, fingerprint, orderNo, toView(order));
135	        return new IdempotentResult<>(request.requestId(), false, toView(order));
136	    }
137	
138	    /** 方式判定：克重差 ≤10%（含）直切；灰分等级差 &gt;2 级须冲洗网部，恰 2 级合法直切。 */
139	    @Transactional
140	    public OrderView decide(String orderNo) {
141	        TransitionOrder order = requireOrder(orderNo);
142	        requireStatus(order, TransitionStatus.APPLIED);
143	
144	        BigDecimal from = order.getBasisWeightFrom();
145	        BigDecimal delta = TransitionRules.basisWeightDeltaPct(from, order.getBasisWeightTo());
146	        int ashDelta = TransitionRules.ashLevelDelta(order.getAshLevelFrom(), order.getAshLevelTo());
147	
148	        order.setBasisWeightDeltaPct(delta);
149	        order.setAshLevelDelta(ashDelta);
150	        // 恰 10.0000% 视为直切。
151	        order.setDirectSwitch(TransitionRules.isDirectSwitch(delta));
152	        // 恰 2 级合法直切；超过 2 级才冲洗网部。
153	        order.setWireFlush(TransitionRules.needsWireFlush(ashDelta));
154	        order.setStatus(TransitionStatus.DECIDED);
155	        order.setDecidedAt(now());
156	        orderRepository.updateDecision(order);
157	        return toView(order);
158	    }
159	
160	    /** 执行：参数须在新品种工艺窗口内（含边界）；过渡料长度 = 车速×切换时间/60。 */
161	    @Transactional
162	    public OrderView execute(String orderNo, ExecuteOrderRequest request) {
163	        TransitionOrder order = requireOrder(orderNo);
164	        requireStatus(order, TransitionStatus.DECIDED);
165	        if (request.switchTimeSec() <= 0) {
166	            throw ApiException.badRequest("切换时间须为正整数秒");
167	        }
168	        Grade toGrade = gradeRepository.findByCode(order.getToGrade())
169	                .orElseThrow(() -> ApiException.badRequest("新品种不存在: " + order.getToGrade()));
170	
171	        BigDecimal speed = request.machineSpeedMMin();
172	        BigDecimal consistency = request.stockConsistencyPct();
173	        // 恰在窗口边界视为合格。
174	        if (!TransitionRules.withinWindow(speed, toGrade.getSpeedMin(), toGrade.getSpeedMax())) {
175	            throw ApiException.badRequest("执行车速 " + speed + " 超出新品种工艺窗口 ["
176	                    + toGrade.getSpeedMin() + ", " + toGrade.getSpeedMax() + "] m/min");
177	        }
178	        if (!TransitionRules.withinWindow(consistency, toGrade.getConsistencyMin(),
179	                toGrade.getConsistencyMax())) {
180	            throw ApiException.badRequest("上料浓度 " + consistency + " 超出新品种工艺窗口 ["
181	                    + toGrade.getConsistencyMin() + ", " + toGrade.getConsistencyMax() + "] %");
182	        }
183	
184	        BigDecimal length = TransitionRules.transitionLengthM(speed, request.switchTimeSec());
185	
186	        order.setSwitchTimeSec(request.switchTimeSec());
187	        order.setMachineSpeedMMin(speed);
188	        order.setStockConsistencyPct(consistency);
189	        order.setTransitionLengthM(length);
190	        order.setStatus(TransitionStatus.EXECUTED);
191	        order.setExecutedAt(now());
192	        orderRepository.updateExecution(order);
193	
194	        // 停机清洗才占用清洗窗口；与执行结果在同一事务内登记，直切绝不产生清洗占用。
195	        if (Boolean.FALSE.equals(order.getDirectSwitch())) {
196	            String windowNo = "CW-" + orderNo;
197	            if (!cleaningWindowRepository.tryOccupy(windowNo, order.getPaperMachine(), orderNo, now())) {
198	                throw ApiException.conflict("停机清洗窗口冲突，纸机 " + order.getPaperMachine());
199	            }
200	        }
201	        if (cleaningWindowRepository.countActiveForOrder(orderNo) > 0
202	                && Boolean.TRUE.equals(order.getDirectSwitch())) {
203	            // 防御性不变式：直切单不得占用清洗窗口。
204	            throw ApiException.conflict("直切单不得占用清洗窗口");
205	        }
206	        return toView(order);
207	    }
208	
209	    /** 过渡料处置：过渡卷按卷号唯一登记，强制降级、入非正品库。 */
210	    @Transactional
211	    public OrderView dispose(String orderNo, DisposeRollsRequest request) {
212	        TransitionOrder order = requireOrder(orderNo);
213	        requireStatus(order, TransitionStatus.EXECUTED);
214	
215	        List<String> rollNos = request.rolls().stream().map(DisposeRollsRequest.RollItem::rollNo).toList();
216	        if (rollNos.stream().distinct().count() != rollNos.size()) {
217	            throw ApiException.conflict("同一次处置中卷号重复");
218	        }
219	        LocalDateTime registeredAt = now();
220	        try {
221	            for (DisposeRollsRequest.RollItem item : request.rolls()) {
222	                TransitionRoll roll = new TransitionRoll();
223	                roll.setRollNo(item.rollNo());
224	                roll.setOrderNo(orderNo);
225	                roll.setPaperMachine(order.getPaperMachine());
226	                roll.setLengthM(item.lengthM());
227	                rollRepository.insertDowngraded(roll, registeredAt);
228	                verdictEventRepository.insert(item.rollNo(), "FORCED_DOWNGRADE", null,
229	                        "DOWNGRADED", null, registeredAt);
230	            }
231	        } catch (DuplicateKeyException e) {
232	            throw ApiException.conflict("卷号已登记，过渡纸卷按卷号唯一");
233	        }
234	
235	        order.setStatus(TransitionStatus.DISPOSED);
236	        order.setDisposedAt(registeredAt);
237	        orderRepository.updateStatus(orderNo, TransitionStatus.DISPOSED, "disposed_at", registeredAt);
238	        return toView(order);
239	    }
240	
241	    /** 完成：释放纸机占用与清洗窗口，允许同机后续申请。 */
242	    @Transactional
243	    public OrderView complete(String orderNo) {
244	        TransitionOrder order = requireOrder(orderNo);
245	        requireStatus(order, TransitionStatus.DISPOSED);
246	        LocalDateTime completedAt = now();
247	        orderRepository.updateStatus(orderNo, TransitionStatus.COMPLETED, "completed_at", completedAt);
248	        machineSlotRepository.release(order.getPaperMachine(), orderNo);
249	        cleaningWindowRepository.release(orderNo, completedAt);
250	        order.setStatus(TransitionStatus.COMPLETED);
251	        order.setCompletedAt(completedAt);
252	        return toView(order);
253	    }
254	
255	    /** 归档（终态）：重复归档返回幂等成功；未完成不得归档。 */
256	    @Transactional
257	    public OrderView archive(String orderNo) {
258	        TransitionOrder order = requireOrder(orderNo);
259	        if (TransitionStatus.ARCHIVED.equals(order.getStatus())) {
260	            return toView(order);
261	        }
262	        requireStatus(order, TransitionStatus.COMPLETED);
263	        LocalDateTime archivedAt = now();
264	        orderRepository.updateStatus(orderNo, TransitionStatus.ARCHIVED, "archived_at", archivedAt);
265	        order.setStatus(TransitionStatus.ARCHIVED);
266	        order.setArchivedAt(archivedAt);
267	        return toView(order);
268	    }
269	
270	    public OrderView getOrder(String orderNo) {
271	        return toView(requireOrder(orderNo));
272	    }
273	
274	    /** 首次检验提交（requestId 幂等）；达门槛仅取得复议资格，过渡卷仍强制降级。 */
275	    @Transactional
276	    public IdempotentResult<RollView> submitInspection(InspectionRequest request) {
277	        String fingerprint = FingerprintUtil.sha256(request.requestId(), request);
278	        IdempotentRequest existing = lookupIdempotent(request.requestId(), BIZ_INSPECTION, fingerprint);
279	        if (existing != null) {
280	            return replay(existing, new TypeReference<RollView>() {
281	            });
282	        }
283	
284	        TransitionRoll roll = requireRoll(request.rollNo());
285	        TransitionOrder order = requireOrder(roll.getOrderNo());
286	
287	        // 归档终态后迟到：只记迟到事件，不改任何判定与入库状态；重放不重复登记事件。
288	        if (TransitionStatus.ARCHIVED.equals(order.getStatus())) {
289	            lateEventRepository.insert(order.getOrderNo(), roll.getRollNo(), "LATE_INSPECTION",
290	                    writeJson(request), now());
291	            RollView view = toRollView(roll);
292	            registerIdempotent(request.requestId(), BIZ_INSPECTION, fingerprint,
293	                    roll.getRollNo(), view);
294	            return new IdempotentResult<>(request.requestId(), false, view);
295	        }
296	
297	        boolean meets = meetsThreshold(request, order);
298	        try {
299	            RollInspection inspection = new RollInspection();
300	            inspection.setRollNo(roll.getRollNo());
301	            inspection.setInspectionType(INSPECTION_INITIAL);
302	            inspection.setRequestId(request.requestId());
303	            inspection.setAshValuePct(request.ashValuePct());
304	            inspection.setMoisturePct(request.moisturePct());
305	            inspection.setTensileIndex(request.tensileIndex());
306	            inspection.setBasisWeightGM2(request.basisWeightGM2());
307	            inspection.setMeetsThreshold(meets);
308	            // 过渡卷强制降级：达门槛只标记可复议，不自动改判。
309	            inspection.setVerdict(meets ? "GENUINE_ELIGIBLE" : "BELOW_THRESHOLD");
310	            inspectionRepository.insert(inspection, now());
311	        } catch (DuplicateKeyException e) {
312	            throw ApiException.conflict("该卷首次检验已提交");
313	        }
314	        rollRepository.updateInitialEligibility(roll.getRollNo(), meets);
315	
316	        TransitionRoll refreshed = rollRepository.getByRollNo(roll.getRollNo());
317	        registerIdempotent(request.requestId(), BIZ_INSPECTION, fingerprint,
318	                roll.getRollNo(), toRollView(refreshed));
319	        return new IdempotentResult<>(request.requestId(), false, toRollView(refreshed));
320	    }
321	
322	    /** 复议提交（requestId 幂等）：每卷至多受理一次，与首次判定并发形成唯一终态。 */
323	    @Transactional
324	    public IdempotentResult<RollView> submitReexam(ReexamRequest request) {
325	        String fingerprint = FingerprintUtil.sha256(request.requestId(), request);
326	        IdempotentRequest existing = lookupIdempotent(request.requestId(), BIZ_REEXAM, fingerprint);
327	        if (existing != null) {
328	            return replay(existing, new TypeReference<RollView>() {
329	            });
330	        }
331	
332	        TransitionRoll roll = requireRoll(request.rollNo());
333	        TransitionOrder order = requireOrder(roll.getOrderNo());
334	
335	        // 归档终态后迟到的复议：只记迟到事件，终态不变；重放不重复登记事件。
336	        if (TransitionStatus.ARCHIVED.equals(order.getStatus())) {
337	            lateEventRepository.insert(order.getOrderNo(), roll.getRollNo(), "LATE_REEXAM",
338	                    writeJson(request), now());
339	            RollView view = toRollView(roll);
340	            registerIdempotent(request.requestId(), BIZ_REEXAM, fingerprint,
341	                    roll.getRollNo(), view);
342	            return new IdempotentResult<>(request.requestId(), false, view);
343	        }
344	
345	        boolean initialEligible = inspectionRepository.find(roll.getRollNo(), INSPECTION_INITIAL)
346	                .map(RollInspection::isMeetsThreshold).orElse(false);
347	        if (!initialEligible) {
348	            throw ApiException.conflict("首次检验未达正品门槛或尚未检验，不具备复议资格");
349	        }
350	        if (roll.getReexamCount() > 0 || "UPGRADED".equals(roll.getVerdict())) {
351	            throw ApiException.conflict("该卷复议仅允许一次，终态已确定");
352	        }
353	
354	        boolean meets = meetsThreshold(request, order);
355	        LocalDateTime eventTime = now();
356	        try {
357	            RollInspection inspection = new RollInspection();
358	            inspection.setRollNo(roll.getRollNo());
359	            inspection.setInspectionType(INSPECTION_REEXAM);
360	            inspection.setRequestId(request.requestId());
361	            inspection.setAshValuePct(request.ashValuePct());
362	            inspection.setMoisturePct(request.moisturePct());
363	            inspection.setTensileIndex(request.tensileIndex());
364	            inspection.setBasisWeightGM2(request.basisWeightGM2());
365	            inspection.setMeetsThreshold(meets);
366	            inspection.setVerdict(meets ? "REEXAM_UPGRADED" : "REEXAM_REJECTED");
367	            // 唯一约束 (roll_no, inspection_type)：并发复议只有一个能插入，形成唯一终态。
368	            inspectionRepository.insert(inspection, eventTime);
369	        } catch (DuplicateKeyException e) {
370	            throw ApiException.conflict("该卷复议已受理，终态唯一");
371	        }
372	
373	        if (meets) {
374	            int updated = rollRepository.applyUpgrade(roll.getRollNo(), eventTime);
375	            if (updated == 0) {
376	                throw ApiException.conflict("该卷终态已确定，复议改判失败");
377	            }
378	            verdictEventRepository.insert(roll.getRollNo(), "REEXAM_UPGRADED",
379	                    "DOWNGRADED", "UPGRADED", request.requestId(), eventTime);
380	        } else {
381	            int updated = rollRepository.applyReexamReject(roll.getRollNo());
382	            if (updated == 0) {
383	                throw ApiException.conflict("该卷终态已确定，复议驳回失败");
384	            }
385	            verdictEventRepository.insert(roll.getRollNo(), "REEXAM_REJECTED",
386	                    "DOWNGRADED", "DOWNGRADED", request.requestId(), eventTime);
387	        }
388	
389	        TransitionRoll refreshed = rollRepository.getByRollNo(roll.getRollNo());
390	        registerIdempotent(request.requestId(), BIZ_REEXAM, fingerprint,
391	                roll.getRollNo(), toRollView(refreshed));
392	        return new IdempotentResult<>(request.requestId(), false, toRollView(refreshed));
393	    }
394	
395	    public RollView getRoll(String rollNo) {
396	        return toRollView(requireRoll(rollNo));
397	    }
398	
399	    /** 过渡料长度、降级卷明细与改判链复算。 */
400	    public TransitionRecomputeView recompute(String orderNo) {
401	        TransitionOrder order = requireOrder(orderNo);
402	        BigDecimal recomputed = null;
403	        if (order.getMachineSpeedMMin() != null && order.getSwitchTimeSec() != null) {
404	            recomputed = TransitionRules.transitionLengthM(
405	                    order.getMachineSpeedMMin(), order.getSwitchTimeSec());
406	        }
407	        List<RollView> rolls = rollRepository.findByOrderNo(orderNo).stream()
408	                .map(this::toRollView).toList();
409	        BigDecimal sumLength = rolls.stream()
410	                .map(RollView::lengthM)
411	                .filter(java.util.Objects::nonNull)
412	                .reduce(BigDecimal.ZERO, BigDecimal::add);
413	        return new TransitionRecomputeView(orderNo, order.getSwitchTimeSec(),
414	                order.getMachineSpeedMMin(), order.getTransitionLengthM(), recomputed,
415	                sumLength, rolls);
416	    }
417	
418	    // ------------------------------------------------------------------
419	    // 私有辅助方法（置于作用域末尾）
420	    // ------------------------------------------------------------------
421	
422	    private LocalDateTime now() {
423	        return LocalDateTime.now(clock);
424	    }
425	
426	    private TransitionOrder requireOrder(String orderNo) {
427	        return orderRepository.findByOrderNo(orderNo)
428	                .orElseThrow(() -> ApiException.notFound("改品种单不存在: " + orderNo));
429	    }
430	
431	    private TransitionRoll requireRoll(String rollNo) {
432	        return rollRepository.findByRollNo(rollNo)
433	                .orElseThrow(() -> ApiException.notFound("过渡纸卷不存在: " + rollNo));
434	    }
435	
436	    private void requireStatus(TransitionOrder order, String expected) {
437	        if (!expected.equals(order.getStatus())) {
438	            throw ApiException.conflict("改品种单状态为 " + order.getStatus()
439	                    + "，不允许该操作，期望状态 " + expected);
440	        }
441	    }
442	
443	    /**
444	     * 幂等记录查询：同键同参返回已完成的首次记录（调用方重放）；同键异参抛 409。
445	     * 读到未完成占位（首次事务尚未提交结果）时等待重试；查无记录则尝试插入占位，
446	     * 占位插入成功表示当前请求获得受理权，唯一索引冲突时重新查询。
447	     */
448	    private IdempotentRequest lookupIdempotent(String requestId, String bizType, String fingerprint) {
449	        for (int i = 0; i < 25; i++) {
450	            Optional<IdempotentRequest> found = idempotentRequestRepository.find(requestId);
451	            if (found.isPresent()) {
452	                IdempotentRequest record = found.get();
453	                if (!bizType.equals(record.getBizType()) || !fingerprint.equals(record.getFingerprint())) {
454	                    throw ApiException.conflict("requestId=" + requestId + " 已用于不同业务参数，冲突拒绝");
455	                }
456	                if (record.getResultJson() != null) {
457	                    return record;
458	                }
459	                // 首次事务仍在进行，等待其提交后重放。
460	                sleepBriefly();
461	                continue;
462	            }
463	            try {
464	                IdempotentRequest placeholder = new IdempotentRequest();
465	                placeholder.setRequestId(requestId);
466	                placeholder.setBizType(bizType);
467	                placeholder.setFingerprint(fingerprint);
468	                placeholder.setResultRef(null);
469	                placeholder.setResultJson(null);
470	                idempotentRequestRepository.insert(placeholder, now());
471	                return null;
472	            } catch (DuplicateKeyException e) {
473	                // 并发请求已插入占位（可能未提交），等待后重新查询。
474	                sleepBriefly();
475	            }
476	        }
477	        throw ApiException.conflict("并发幂等请求处理中，请稍后重放: " + requestId);
478	    }
479	
480	    private void sleepBriefly() {
481	        try {
482	            Thread.sleep(20);
483	        } catch (InterruptedException ie) {
484	            Thread.currentThread().interrupt();
485	            throw ApiException.conflict("并发幂等请求处理中断");
486	        }
487	    }
488	
489	    private void registerIdempotent(String requestId, String bizType, String fingerprint,
490	                                    String resultRef, Object resultView) {
491	        idempotentRequestRepository.updateResult(requestId, resultRef, writeJson(resultView));
492	    }
493	
494	    private <T> IdempotentResult<T> replay(IdempotentRequest record, TypeReference<T> type) {
495	        T data;
496	        try {
497	            byte[] bytes = record.getResultJson() == null
498	                    ? new byte[0] : record.getResultJson().getBytes(StandardCharsets.UTF_8);
499	            data = objectMapper.readValue(bytes, type);
500	        } catch (Exception e) {
501	            throw new IllegalStateException("幂等首次结果反序列化失败", e);
502	        }
503	        return new IdempotentResult<>(record.getRequestId(), true, data);
504	    }
505	
506	    private String writeJson(Object value) {
507	        try {
508	            return objectMapper.writeValueAsString(value);
509	        } catch (Exception e) {
510	            throw new IllegalStateException("JSON 序列化失败", e);
511	        }
512	    }
513	
514	    /**
515	     * 合成正品门槛判定（恰达边界视为合格）：
516	     * 灰分 ≤18%，水分 ∈ [4%,8%]，抗张指数 ≥45 Nm/g，定量与新品种标称克重偏差 ≤3%。
517	     */
518	    private boolean meetsThreshold(Object request, TransitionOrder order) {
519	        BigDecimal ash;
520	        BigDecimal moisture;
521	        BigDecimal tensile;
522	        BigDecimal basisWeight;
523	        if (request instanceof InspectionRequest ir) {
524	            ash = ir.ashValuePct();
525	            moisture = ir.moisturePct();
526	            tensile = ir.tensileIndex();
527	            basisWeight = ir.basisWeightGM2();
528	        } else {
529	            ReexamRequest rr = (ReexamRequest) request;
530	            ash = rr.ashValuePct();
531	            moisture = rr.moisturePct();
532	            tensile = rr.tensileIndex();
533	            basisWeight = rr.basisWeightGM2();
534	        }
535	        Grade toGrade = gradeRepository.findByCode(order.getToGrade())
536	                .orElseThrow(() -> ApiException.notFound("新品种不存在: " + order.getToGrade()));
537	        return TransitionRules.meetsQualityThreshold(ash, moisture, tensile,
538	                basisWeight, toGrade.getBasisWeight());
539	    }
540	
541	    private String newOrderNo() {
542	        byte[] bytes = new byte[2];
543	        RANDOM.nextBytes(bytes);
544	        return "TO-" + now().format(NO_FORMAT) + "-" + HexFormat.of().formatHex(bytes);
545	    }
546	
547	    private OrderView toView(TransitionOrder o) {
548	        return new OrderView(o.getOrderNo(), o.getPaperMachine(), o.getFromGrade(), o.getToGrade(),
549	                o.getBasisWeightFrom(), o.getBasisWeightTo(), o.getAshLevelFrom(), o.getAshLevelTo(),
550	                o.getBasisWeightDeltaPct(), o.getAshLevelDelta(), o.getDirectSwitch(), o.getWireFlush(),
551	                o.getSwitchTimeSec(), o.getMachineSpeedMMin(), o.getStockConsistencyPct(),
552	                o.getTransitionLengthM(), o.getStatus(), o.getAppliedAt(), o.getDecidedAt(),
553	                o.getExecutedAt(), o.getDisposedAt(), o.getCompletedAt(), o.getArchivedAt());
554	    }
555	
556	    private RollView toRollView(TransitionRoll r) {
557	        return new RollView(r.getRollNo(), r.getOrderNo(), r.getPaperMachine(), r.getLengthM(),
558	                r.getVerdict(), r.getWarehouseStatus(), r.isEligibleReexam(), r.getReexamCount(),
559	                r.getRegisteredAt(), r.getVerdictChangedAt(),
560	                verdictEventRepository.findByRollNo(r.getRollNo()));
561	    }
562	}
