17	    public static final BigDecimal ASH_MAX_PCT = new BigDecimal("18.000");
18	    public static final BigDecimal MOISTURE_MIN_PCT = new BigDecimal("4.000");
19	    public static final BigDecimal MOISTURE_MAX_PCT = new BigDecimal("8.000");
20	    public static final BigDecimal TENSILE_MIN = new BigDecimal("45.000");
