1	package com.example.starter.transition.repo;
2	
3	import com.example.starter.transition.model.TransitionOrder;
4	import org.springframework.jdbc.core.JdbcTemplate;
5	import org.springframework.jdbc.core.RowMapper;
6	import org.springframework.stereotype.Repository;
7	
8	import java.sql.Timestamp;
9	import java.util.List;
10	import java.util.Optional;
11	
12	/**
13	 * 改品种单仓储。
14	 */
15	@Repository
16	public class TransitionOrderRepository {
17	
18	    private static final RowMapper<TransitionOrder> MAPPER = (rs, n) -> {
19	        TransitionOrder o = new TransitionOrder();
20	        o.setId(rs.getLong("id"));
21	        o.setOrderNo(rs.getString("order_no"));
22	        o.setPaperMachine(rs.getString("paper_machine"));
23	        o.setFromGrade(rs.getString("from_grade"));
24	        o.setToGrade(rs.getString("to_grade"));
25	        o.setBasisWeightFrom(rs.getBigDecimal("basis_weight_from"));
26	        o.setBasisWeightTo(rs.getBigDecimal("basis_weight_to"));
27	        o.setAshLevelFrom(rs.getInt("ash_level_from"));
28	        o.setAshLevelTo(rs.getInt("ash_level_to"));
29	        o.setBasisWeightDeltaPct(rs.getBigDecimal("basis_weight_delta_pct"));
30	        Integer ashDelta = rs.getObject("ash_level_delta", Integer.class);
31	        o.setAshLevelDelta(ashDelta);
32	        o.setDirectSwitch(getNullableBoolean(rs, "direct_switch"));
33	        o.setWireFlush(getNullableBoolean(rs, "wire_flush"));
34	        o.setSwitchTimeSec(rs.getObject("switch_time_sec", Integer.class));
35	        o.setMachineSpeedMMin(rs.getBigDecimal("machine_speed_m_min"));
36	        o.setStockConsistencyPct(rs.getBigDecimal("stock_consistency_pct"));
37	        o.setTransitionLengthM(rs.getBigDecimal("transition_length_m"));
38	        o.setStatus(rs.getString("status"));
39	        o.setAppliedRequestId(rs.getString("applied_request_id"));
40	        o.setAppliedAt(rs.getTimestamp("applied_at").toLocalDateTime());
41	        Timestamp decided = rs.getTimestamp("decided_at");
42	        o.setDecidedAt(decided == null ? null : decided.toLocalDateTime());
43	        Timestamp executed = rs.getTimestamp("executed_at");
44	        o.setExecutedAt(executed == null ? null : executed.toLocalDateTime());
45	        Timestamp disposed = rs.getTimestamp("disposed_at");
46	        o.setDisposedAt(disposed == null ? null : disposed.toLocalDateTime());
47	        Timestamp completed = rs.getTimestamp("completed_at");
48	        o.setCompletedAt(completed == null ? null : completed.toLocalDateTime());
49	        Timestamp archived = rs.getTimestamp("archived_at");
50	        o.setArchivedAt(archived == null ? null : archived.toLocalDateTime());
51	        return o;
52	    };
53	
54	    private final JdbcTemplate jdbc;
55	
56	    public TransitionOrderRepository(JdbcTemplate jdbc) {
57	        this.jdbc = jdbc;
58	    }
59	
60	    public void insert(TransitionOrder o) {
61	        jdbc.update("""
62	                        INSERT INTO transition_order (
63	                            order_no, paper_machine, from_grade, to_grade,
64	                            basis_weight_from, basis_weight_to, ash_level_from, ash_level_to,
65	                            status, applied_request_id, applied_at)
66	                        VALUES (?,?,?,?,?,?,?,?,?,?,?)
67	                        """,
68	                o.getOrderNo(), o.getPaperMachine(), o.getFromGrade(), o.getToGrade(),
69	                o.getBasisWeightFrom(), o.getBasisWeightTo(),
70	                o.getAshLevelFrom(), o.getAshLevelTo(),
71	                o.getStatus(), o.getAppliedRequestId(), Timestamp.valueOf(o.getAppliedAt()));
72	    }
73	
74	    public Optional<TransitionOrder> findByOrderNo(String orderNo) {
75	        List<TransitionOrder> list = jdbc.query(
76	                "SELECT * FROM transition_order WHERE order_no = ?", MAPPER, orderNo);
77	        return list.stream().findFirst();
78	    }
79	
80	    public TransitionOrder getByOrderNo(String orderNo) {
81	        return findByOrderNo(orderNo).orElseThrow(() ->
82	                new IllegalArgumentException("改品种单不存在: " + orderNo));
83	    }
84	
85	    /** 方式判定结果回写。 */
86	    public void updateDecision(TransitionOrder o) {
87	        jdbc.update("""
88	                        UPDATE transition_order
89	                        SET basis_weight_delta_pct = ?, ash_level_delta = ?,
90	                            direct_switch = ?, wire_flush = ?,
91	                            status = ?, decided_at = ?
92	                        WHERE order_no = ?
93	                        """,
94	                o.getBasisWeightDeltaPct(), o.getAshLevelDelta(),
95	                o.getDirectSwitch(), o.getWireFlush(),
96	                o.getStatus(), Timestamp.valueOf(o.getDecidedAt()), o.getOrderNo());
97	    }
98	
99	    /** 执行结果回写：工艺参数、切换时间、过渡料长度。 */
100	    public void updateExecution(TransitionOrder o) {
101	        jdbc.update("""
102	                        UPDATE transition_order
103	                        SET switch_time_sec = ?, machine_speed_m_min = ?,
104	                            stock_consistency_pct = ?, transition_length_m = ?,
105	                            status = ?, executed_at = ?
106	                        WHERE order_no = ?
107	                        """,
108	                o.getSwitchTimeSec(), o.getMachineSpeedMMin(),
109	                o.getStockConsistencyPct(), o.getTransitionLengthM(),
110	                o.getStatus(), Timestamp.valueOf(o.getExecutedAt()), o.getOrderNo());
111	    }
112	
113	    public void updateStatus(String orderNo, String status, String timeColumn,
114	                             java.time.LocalDateTime time) {
115	        jdbc.update("UPDATE transition_order SET status = ?, " + timeColumn + " = ? WHERE order_no = ?",
116	                status, Timestamp.valueOf(time), orderNo);
117	    }
118	
119	    private static Boolean getNullableBoolean(java.sql.ResultSet rs, String column)
120	            throws java.sql.SQLException {
121	        Integer v = rs.getObject(column, Integer.class);
122	        return v == null ? null : v != 0;
123	    }
124	}
