91	                    "c-same-key", "PM-C2", "G-A4-70", "G-A4-77"));
92	            if (result.replayed()) {
93	                replayed.incrementAndGet();
94	            } else {
95	                created.incrementAndGet();
96	            }
97	        }, ex -> {
98	            throw new AssertionError("同键同参并发不应抛异常", ex);
99	        });
