111	    void concurrentReexamProducesSingleFinalVerdict() throws Exception {
112	        prepareRollWithEligibleInspection("c-roll-1", "PM-C3", "c-order-1");
113	
114	        CyclicBarrier barrier = new CyclicBarrier(2);
115	        AtomicInteger upgraded = new AtomicInteger();
116	        AtomicInteger conflict = new AtomicInteger();
117	        runConcurrently(2, i -> {
118	            barrier.await(10, TimeUnit.SECONDS);
119	            IdempotentResult<RollView> result = service.submitReexam(new ReexamRequest(
120	                    "c-rex-" + i, "c-roll-1", new BigDecimal("17.000"), new BigDecimal("6.000"),
121	                    new BigDecimal("47.000"), new BigDecimal("77.00")));
122	            if ("UPGRADED".equals(result.data().verdict())) {
123	                upgraded.incrementAndGet();
124	            }
125	        }, ex -> {
126	            if (ex instanceof ApiException api && api.getStatus() == 409) {
127	                conflict.incrementAndGet();
128	            } else {
129	                throw new AssertionError("非预期异常", ex);
130	            }
131	        });
132	
133	        assertEquals(1, upgraded.get(), "唯一改判成功");
134	        assertEquals(1, conflict.get(), "并发复议唯一终态");
135	        RollView roll = service.getRoll("c-roll-1");
136	        assertEquals("UPGRADED", roll.verdict());
137	        assertEquals("GENUINE", roll.warehouseStatus());
138	        assertEquals(1, roll.reexamCount());
139	        assertEquals(1L, jdbc.queryForObject(
140	                "SELECT COUNT(1) FROM roll_inspection WHERE roll_no = 'c-roll-1' AND inspection_type = 'REEXAM'",
141	                Long.class), "复议检验记录唯一");
142	        assertEquals(1L, jdbc.queryForObject(
143	                "SELECT COUNT(1) FROM roll_verdict_event WHERE roll_no = 'c-roll-1' AND event_type = 'REEXAM_UPGRADED'",
144	                Long.class), "改判链中改判事件唯一");
145	    }
