147	    // ------------------------------------------------------------------
148	    // 测试辅助
149	    // ------------------------------------------------------------------
150	
151	    private void prepareRollWithEligibleInspection(String rollNo, String machine, String requestPrefix) {
152	        OrderView applied = service.apply(new ApplyOrderRequest(
153	                requestPrefix + "-apply", machine, "G-A4-70", "G-A4-77")).data();
154	        service.decide(applied.orderNo());
155	        service.execute(applied.orderNo(), new ExecuteOrderRequest(
156	                new BigDecimal("900.000"), new BigDecimal("1.000"), 60));
157	        service.dispose(applied.orderNo(), new DisposeRollsRequest(List.of(
158	                new DisposeRollsRequest.RollItem(rollNo, new BigDecimal("900.000")))));
159	        service.submitInspection(new InspectionRequest(
160	                requestPrefix + "-insp", rollNo, new BigDecimal("18.000"), new BigDecimal("4.000"),
161	                new BigDecimal("45.000"), new BigDecimal("77.00")));
162	        assertTrue(service.getRoll(rollNo).eligibleReexam());
163	    }
164	
165	    private void runConcurrently(ConcurrentAction action, ErrorHandler handler) throws Exception {
166	        runConcurrently(THREADS, action, handler);
167	    }
168	
169	    private void runConcurrently(int threads, ConcurrentAction action, ErrorHandler handler)
170	            throws Exception {
171	        ExecutorService pool = Executors.newFixedThreadPool(threads);
172	        try {
173	            List<Future<Void>> futures = IntStream.range(0, threads)
174	                    .mapToObj(i -> (java.util.concurrent.Callable<Void>) () -> {
175	                        try {
176	                            action.run(i);
177	                        } catch (BrokenBarrierException | InterruptedException e) {
178	                            throw new AssertionError("并发同步失败", e);
179	                        } catch (Exception e) {
180	                            handler.handle(e);
181	                        }
182	                        return null;
183	                    })
184	                    .map(pool::submit)
185	                    .toList();
186	            for (Future<?> future : futures) {
187	                future.get(30, TimeUnit.SECONDS);
188	            }
189	        } finally {
190	            pool.shutdownNow();
191	            assertTrue(pool.awaitTermination(10, TimeUnit.SECONDS));
192	        }
193	    }
194	
195	    @FunctionalInterface
196	    private interface ConcurrentAction {
197	        void run(int index) throws Exception;
198	    }
199	
200	    @FunctionalInterface
201	    private interface ErrorHandler {
202	        void handle(Exception ex);
203	    }
204	}
