51	                .andReturn().getResponse().getContentAsString();
52	
53	        String orderNo = com.jayway.jsonpath.JsonPath.read(response, "$.data.orderNo");
54	
55	        // 同键同参重放：200 + replayed=true
56	        mockMvc.perform(post("/api/transitions/orders")
57	                        .contentType(MediaType.APPLICATION_JSON).content(applyBody))
58	                .andExpect(status().isOk())
59	                .andExpect(jsonPath("$.replayed").value(true))
60	                .andExpect(jsonPath("$.data.orderNo").value(orderNo));
61	
62	        // 同键异参：409
63	        mockMvc.perform(post("/api/transitions/orders")
64	                        .contentType(MediaType.APPLICATION_JSON)
