72	                .andExpect(status().isOk())
73	                .andExpect(jsonPath("$.directSwitch").value(true))
74	                .andExpect(jsonPath("$.wireFlush").value(false))
75	                .andExpect(jsonPath("$.basisWeightDeltaPct").value(10.0000));
76	
77	        // 越界执行：400（单据仍为 DECIDED，先校验工艺窗口）
