114	                .andExpect(jsonPath("$.recomputedTransitionLengthM").value(1640.000))
115	                .andExpect(jsonPath("$.sumRollLengthM").value(1640.000))
116	                .andExpect(jsonPath("$.rolls", hasSize(2)));
