    // ------------------------------------------------------------------
    // 测试辅助
    // ------------------------------------------------------------------

    /** 申请携带比例（同事务判定）并执行，返回 EXECUTED 状态单据。 */
    private OrderView applyWithRatioAndExecute(String requestId, String machine, String ratio) {
